diff --git a/code/frontier_solution/connectivity.h b/code/frontier_solution/connectivity.h
new file mode 100644
index 0000000..4aa1620
--- /dev/null
+++ b/code/frontier_solution/connectivity.h
@@ -0,0 +1,415 @@
+#ifndef FRONTIER_CONNECTIVITY_H
+#define FRONTIER_CONNECTIVITY_H
+
+#include <atomic>
+#include <cstring>
+#include <memory>
+
+namespace frontier {
+
+using GridId = GdLongDataType;
+using PointId = PtLongDataType;
+using Axis = OtLongDataType;
+using Coord = PtDataType;
+
+// A parent can only be hooked to a smaller root. A stale read can cause
+// another search, but cannot create a cycle or separate a component.
+class Components {
+  std::unique_ptr<std::atomic<GridId>[]> parent;
+
+ public:
+  explicit Components(GridId n) : parent(new std::atomic<GridId>[n]) {}
+
+  void makeSet(GridId i) { parent[i].store(i, std::memory_order_relaxed); }
+
+  GridId find(GridId i) const {
+    GridId p = parent[i].load(std::memory_order_relaxed);
+    while (p != i) {
+      GridId next = parent[p].load(std::memory_order_relaxed);
+      if (p != next) parent[i].store(next, std::memory_order_relaxed);
+      i = p;
+      p = next;
+    }
+    return i;
+  }
+
+  void join(GridId a, GridId b) {
+    for (;;) {
+      a = find(a);
+      b = find(b);
+      if (a == b) return;
+      if (a < b) std::swap(a, b);
+      if (parent[a].compare_exchange_weak(a, b, std::memory_order_relaxed)) return;
+    }
+  }
+};
+
+struct CoreCell {
+  Coord *witness;
+  PointId first, end;
+};
+
+inline CoreCell readCoreCell(Grids *grids, GridId g, const intT *core) {
+  PointId first = grids->GetStartOffset(g);
+  PointId end = first + grids->GetNumPts(g);
+  while (!core[grids->GetPt(first)]) ++first;
+  return {grids->GetPtData(first), first, end};
+}
+
+// A star is a set of cells whose core witnesses are all within epsilon of
+// its center witness. Every member is therefore in one core component.
+template <int FixedDim>
+class StarGraph {
+  struct Cell : CoreCell {
+    GridId center, next, head;
+  };
+
+  struct Range {
+    GridId first, end;
+  };
+
+  Grids *grids;
+  const intT *core;
+  const bool *coreGrid;
+  const Coord radius2;
+  const GridId count;
+  const int minPts;
+  const int dim;
+  const Axis reach;
+  std::unique_ptr<Cell[]> cells;
+  std::unique_ptr<Axis[]> bounds;
+  std::unique_ptr<Coord[]> centerCoords;
+  std::unique_ptr<GridId[]> centers;
+  Components components;
+
+  int dims() const { return FixedDim ? FixedDim : dim; }
+
+  GridId buildStars(GridId first, GridId end) {
+    GridId active = first, stop = first, recent = -1;
+    for (GridId g = first; g < end; ++g) {
+      if (!coreGrid[g]) continue;
+      Cell &cell = cells[g];
+      static_cast<CoreCell &>(cell) = readCoreCell(grids, g, core);
+      Axis left = grids->ReadGridVec(g, 0) - reach;
+      while (active < stop && grids->ReadGridVec(centers[active], 0) < left) ++active;
+
+      GridId slot = recent;
+      if (slot < active || !PointDistNDSqrLeq(cell.witness, centerCoords.get() + slot*dims(),
+                                               dims(), radius2)) {
+        slot = stop;
+        for (GridId j = stop; j > active;) {
+          --j;
+          if (j != recent && PointDistNDSqrLeq(cell.witness, centerCoords.get() + j*dims(),
+                                               dims(), radius2)) {
+            slot = j;
+            break;
+          }
+        }
+      }
+      recent = slot;
+      GridId center = slot == stop ? g : centers[slot];
+      if (slot == stop) {
+        components.makeSet(g);
+        std::copy_n(cell.witness, dims(), centerCoords.get() + stop*dims());
+        centers[stop++] = g;
+        cell.head = -1;
+        Axis *box = bounds.get() + 2*g*dims();
+        for (int d = 0; d < dims(); ++d)
+          box[d] = box[dim+d] = grids->ReadGridVec(g, d);
+      } else {
+        Axis *box = bounds.get() + 2*center*dims();
+        for (int d = 0; d < dims(); ++d) {
+          Axis x = grids->ReadGridVec(g, d);
+          box[d] = std::min(box[d], x);
+          box[dim+d] = std::max(box[dim+d], x);
+        }
+      }
+      cell.center = center;
+      cell.next = cells[center].head;
+      cells[center].head = g;
+    }
+    return stop - first;
+  }
+
+  // Box coordinates are grid indices. One grid side is epsilon/sqrt(dim),
+  // so a squared lower bound greater than dim excludes a core-point edge.
+  template <bool SingleA, bool SingleB>
+  bool separated(GridId a, GridId b) const {
+    const Axis *boxA = bounds.get() + 2*a*dims();
+    const Axis *boxB = bounds.get() + 2*b*dims();
+    Axis sum = 0;
+    for (int d = 0; d < dims(); ++d) {
+      Axis lowA = SingleA ? grids->ReadGridVec(a, d) : boxA[d];
+      Axis lowB = SingleB ? grids->ReadGridVec(b, d) : boxB[d];
+      Axis highA = SingleA ? lowA : boxA[dim+d];
+      Axis highB = SingleB ? lowB : boxB[dim+d];
+      Axis delta = std::max(lowA - highB, lowB - highA);
+      if (delta > reach) return true;
+      Axis gap = std::max(Axis(0), delta - 1);
+      sum += gap*gap;
+    }
+    return sum > dim;
+  }
+
+  bool cellEdge(const CoreCell &a, const CoreCell &b) const {
+    for (PointId i = a.first; i < a.end; ++i) {
+      if (!core[grids->GetPt(i)]) continue;
+      Coord *p = grids->GetPtData(i);
+      for (PointId j = b.first; j < b.end; ++j) {
+        if (core[grids->GetPt(j)] && PointDistNDSqrLeq(p, grids->GetPtData(j), dims(), radius2))
+          return true;
+      }
+    }
+    return false;
+  }
+
+  template <bool Exact>
+  bool starEdge(GridId a, GridId b) const {
+    if (PointDistNDSqrLeq(cells[a].witness, cells[b].witness, dims(), radius2)) return true;
+    for (GridId g = cells[a].head; g >= 0; g = cells[g].next) {
+      if (separated<true, false>(g, b)) continue;
+      for (GridId h = cells[b].head; h >= 0; h = cells[h].next) {
+        if (Exact) {
+          if (!separated<true, true>(g, h) && cellEdge(cells[g], cells[h])) return true;
+        } else if (PointDistNDSqrLeq(cells[g].witness, cells[h].witness, dims(), radius2)) {
+          return true;
+        }
+      }
+    }
+    return false;
+  }
+
+  // When sqrt(dim) is integral, two occupied cells can have index
+  // difference sqrt(dim)+1 on a closed-radius floating-point boundary.
+  // The cached query stops at ceil(sqrt(dim)). Add its missing outer slab
+  // for cells whose points will participate in border queries.
+  void includeOuterSlab(GridId g, GridId starCount) {
+    Axis x = grids->ReadGridVec(g, 0);
+    auto end = centers.get() + starCount;
+    auto begin = std::lower_bound(centers.get(), end, x - 2*reach,
+        [&](GridId center, Axis left) { return grids->ReadGridVec(center, 0) < left; });
+    NbrContainer &list = *grids->GetNbrVector(g);
+    for (auto it = begin; it != end; ++it) {
+      GridId center = *it;
+      if (grids->ReadGridVec(center, 0) - x > 2*reach) break;
+      if (separated<true, false>(g, center)) continue;
+      for (GridId h = cells[center].head; h >= 0; h = cells[h].next) {
+        if (separated<true, true>(g, h)) continue;
+        for (int d = 0; d < dims(); ++d) {
+          if (std::abs(grids->ReadGridVec(h, d) - grids->ReadGridVec(g, d)) == reach) {
+            list.push_back(h);
+            break;
+          }
+        }
+      }
+    }
+  }
+
+  // Contract inexpensive witness edges from the cached candidate graph.
+  // A cell containing any non-core point still needs its candidates for
+  // border assignment. A fully core cell can consume its buffer here.
+  // Releasing it on the worker that built it also bounds live graph memory.
+  void contractCachedEdges(GridId starCount) {
+    const bool outerSlab = (reach-1)*(reach-1) == dim;
+    #pragma omp for schedule(static, 1)
+    for (GridId g = 0; g < count; ++g) {
+      if (!coreGrid[g]) {
+        if (outerSlab) includeOuterSlab(g, starCount);
+        continue;
+      }
+      if (!grids->HasFilledNbrVector(g)) continue;
+      const Cell &cell = cells[g];
+      NbrContainer work;
+      NbrContainer *candidates = grids->GetNbrVector(g);
+      bool allCore = cell.first == grids->GetStartOffset(g);
+      for (PointId j = cell.first + 1; j < cell.end && allCore; ++j)
+        allCore = core[grids->GetPt(j)] != 0;
+      if (allCore) {
+        work.swap(*candidates);
+        candidates = &work;
+      }
+      const GridId size = candidates->size();
+      const GridId stride = std::max<GridId>(1, size / 4);
+      GridId root = components.find(cell.center);
+      for (GridId j = g % stride; j < size; j += stride) {
+        GridId h = (*candidates)[j];
+        if (!coreGrid[h] || root == components.find(cells[h].center)) continue;
+        if (PointDistNDSqrLeq(cell.witness, cells[h].witness, dims(), radius2)) {
+          components.join(root, cells[h].center);
+          break;
+        }
+      }
+      if (!allCore && outerSlab) includeOuterSlab(g, starCount);
+    }
+  }
+
+  void joinStars(GridId n, Range *ranges) {
+    #pragma omp for schedule(dynamic, 4)
+    for (GridId i = 0; i < n; ++i) {
+      GridId a = centers[i], root = components.find(a);
+      Range pending = {i, 0};
+      for (GridId j = ranges[i].first; j < i; ++j) {
+        GridId b = centers[j];
+        if (components.find(b) == root || separated<false, false>(a, b)) continue;
+        if (starEdge<false>(a, b)) {
+          components.join(root, b);
+          root = components.find(root);
+        } else {
+          pending.first = std::min(pending.first, j);
+          pending.end = j + 1;
+        }
+      }
+      ranges[i] = pending;
+    }
+
+    // Only unresolved pairs can still require a search of all core points.
+    #pragma omp for schedule(dynamic, 4)
+    for (GridId i = 0; i < n; ++i) {
+      if (ranges[i].first >= ranges[i].end) continue;
+      GridId a = centers[i], root = components.find(a);
+      for (GridId j = ranges[i].first; j < ranges[i].end; ++j) {
+        GridId b = centers[j];
+        if (components.find(b) == root || separated<false, false>(a, b)) continue;
+        if (starEdge<true>(a, b)) {
+          components.join(root, b);
+          root = components.find(root);
+        }
+      }
+    }
+  }
+
+ public:
+  StarGraph(Grids *grids, const intT *core, const bool *coreGrid, const DbscanParams *params)
+      : grids(grids), core(core), coreGrid(coreGrid), radius2(params->m_epsilon * params->m_epsilon),
+        count(grids->GetNumGrids()), minPts(params->m_minPts), dim(grids->GetDim()),
+        reach(1 + static_cast<Axis>(std::sqrt(double(dim)))),
+        cells(new Cell[count]), bounds(new Axis[2*dim*count]),
+        centerCoords(new Coord[dim*count]), centers(new GridId[count]), components(count) {}
+
+  void label(GridId *ids, PointId n) {
+    GridId chunk = std::max<GridId>(128, (count + getWorkers() - 1) / getWorkers());
+    GridId blocks = (count + chunk - 1) / chunk;
+    std::vector<GridId> sizes(blocks);
+    std::unique_ptr<Range[]> ranges(new Range[count]);
+    GridId stop = 0;
+    #pragma omp parallel
+    {
+      #pragma omp for
+      for (GridId b = 0; b < blocks; ++b)
+        sizes[b] = buildStars(b*chunk, std::min(count, (b+1)*chunk));
+
+      #pragma omp single
+      {
+        for (GridId b = 0; b < blocks; ++b) {
+          if (b*chunk != stop)
+            std::memmove(centers.get() + stop, centers.get() + b*chunk, sizes[b]*sizeof(GridId));
+          stop += sizes[b];
+        }
+        GridId first = 0;
+        for (GridId i = 0; i < stop; ++i) {
+          // A possible edge spans at most three radii in grid steps along x,
+          // counting the offsets from both endpoint cells to their centers.
+          Axis left = grids->ReadGridVec(centers[i], 0) - 3*reach;
+          while (grids->ReadGridVec(centers[first], 0) < left) ++first;
+          ranges[i] = {first, i};
+        }
+      }
+      contractCachedEdges(stop);
+      joinStars(stop, ranges.get());
+    }
+
+    #pragma omp parallel for if(n > 32768)
+    for (GridId g = 0; g < count; ++g) {
+      GridId id = coreGrid[g] ? components.find(cells[g].center) : -1;
+      PointId start = grids->GetStartOffset(g), end = start + grids->GetNumPts(g);
+      if (end-start >= minPts) {
+        for (PointId j = start; j < end; ++j) ids[grids->GetPt(j)] = id;
+      } else {
+        for (PointId j = start; j < end; ++j) {
+          PointId p = grids->GetPt(j);
+          ids[p] = core[p] ? id : -1;
+        }
+      }
+    }
+  }
+};
+
+// With few core points the graph fits in a direct pair scan. The input
+// order gives a compact list of vertices and needs no geometric index.
+inline void labelFew(_seq<pointNd> *points, const intT *core, Coord radius2, GridId *ids) {
+  std::vector<PointId> active;
+  for (PointId p = 0; p < points->n; ++p) {
+    ids[p] = -1;
+    if (core[p]) active.push_back(p);
+  }
+  Components components(active.size());
+  for (size_t i = 0; i < active.size(); ++i) components.makeSet(i);
+  for (size_t i = 0; i < active.size(); ++i)
+    for (size_t j = 0; j < i; ++j)
+      if (PointDistNDSqrLeq(points->A[active[i]].m_data, points->A[active[j]].m_data,
+                            points->A[0].m_dim, radius2))
+        components.join(i, j);
+  for (size_t i = 0; i < active.size(); ++i) ids[active[i]] = components.find(i);
+}
+
+// A density-reachable edge must have a core endpoint. Transposing the
+// cached rows of the few core cells builds the full candidate incidence
+// for the remaining cells without scanning noise-to-noise edges.
+inline void sparseIncidence(Grids *grids, const bool *coreGrid, Axis root, bool outerSlab) {
+  const GridId count = grids->GetNumGrids();
+  std::vector<GridId> active;
+  for (GridId g = 0; g < count; ++g)
+    if (coreGrid[g]) active.push_back(g);
+  #pragma omp parallel for schedule(static, 1)
+  for (GridId g = 0; g < count; ++g) {
+    if (!coreGrid[g]) {
+      NbrContainer().swap(*grids->GetNbrVector(g));
+      grids->MarkFilledNbrVector(g);
+    }
+  }
+  for (GridId center : active) {
+    NbrContainer &neighbors = *GetNeighborGridsKDTree(center, grids);
+    if (outerSlab) {
+      // At equality, one axis can be root+1 cells apart and all other
+      // cell-coordinate differences are at most one.
+      for (GridId g = 0; g < count; ++g) {
+        int outerAxes = 0;
+        for (int d = 0; d < grids->GetDim(); ++d) {
+          Axis delta = std::abs(grids->ReadGridVec(center, d) - grids->ReadGridVec(g, d));
+          if (delta <= 1) continue;
+          if (delta != root + 1 || outerAxes != 0) {
+            outerAxes = -1;
+            break;
+          }
+          ++outerAxes;
+        }
+        if (outerAxes == 1) neighbors.push_back(g);
+      }
+    }
+    for (GridId g : neighbors)
+      if (!coreGrid[g]) grids->GetNbrVector(g)->push_back(center);
+  }
+}
+
+inline GridId *cluster(_seq<pointNd> *points, DbscanParams *params, Grids *grids,
+                       const bool *coreGrid, PointId coreCount, const intT *core) {
+  GridId *ids = newA(GridId, points->n);
+  if (coreCount <= 64) {
+    labelFew(points, core, params->m_epsilon * params->m_epsilon, ids);
+    Axis root = static_cast<Axis>(std::sqrt(double(grids->GetDim())));
+    bool outerSlab = root*root == grids->GetDim();
+    if (outerSlab || coreCount <= grids->GetNumGrids()/32)
+      sparseIncidence(grids, coreGrid, root, outerSlab);
+    return ids;
+  }
+  switch (grids->GetDim()) {
+    case 3: StarGraph<3>(grids, core, coreGrid, params).label(ids, points->n); break;
+    case 5: StarGraph<5>(grids, core, coreGrid, params).label(ids, points->n); break;
+    case 7: StarGraph<7>(grids, core, coreGrid, params).label(ids, points->n); break;
+    default: StarGraph<0>(grids, core, coreGrid, params).label(ids, points->n); break;
+  }
+  return ids;
+}
